const config = $input.first().json;
const trigger = $('01. Trigger — Telegram Callback').first().json;
const callback = trigger.callback_query || {};
const data = String(callback.data || '');
const callbackUserId = String(callback.from?.id || '');
const callbackChatId = String(callback.message?.chat?.id || '');
const expectedUserId = String(config.telegram_owner_user_id);
const expectedChatId = String(config.telegram_chat_id);
const isReviewCallback = data.startsWith('review|');
const reviewMatch = data.match(
  /^review\|(approve|deny)\|([A-Za-z0-9_-]{1,48})\|([12])$/,
);

let ok = true;
let userError = '';
let discoveryDate = '';
let rank = 0;

if (callbackUserId !== expectedUserId || callbackChatId !== expectedChatId) {
  ok = false;
  userError = 'This selection is not authorized.';
}

if (isReviewCallback) {
  if (ok && !reviewMatch) {
    ok = false;
    userError = 'This review action is malformed or expired.';
  }

  return [
    {
      json: {
        ...config,
        ok,
        is_review_callback: true,
        review_callback_valid: Boolean(reviewMatch),
        review_action: reviewMatch?.[1] || '',
        review_content_id: reviewMatch?.[2] || '',
        review_version: Number(reviewMatch?.[3] || 0),
        user_error: userError,
        callback_query_id: String(callback.id || ''),
        callback_data: data,
        callback_user_id: callbackUserId,
        callback_chat_id: callbackChatId,
        discovery_date: '',
        rank: 0,
      },
    },
  ];
}

const match = data.match(/^select\|(\d{8})\|([1-5])$/);

if (ok && !match) {
  ok = false;
  userError = 'This selection is malformed or expired.';
}

if (ok) {
  const token = match[1];
  const parsedDate = DateTime.fromFormat(token, 'yyyyLLdd', {
    zone: config.timezone,
  });

  if (!parsedDate.isValid || parsedDate.toFormat('yyyyLLdd') !== token) {
    ok = false;
    userError = 'This selection contains an invalid date.';
  } else {
    discoveryDate = parsedDate.toFormat('yyyy-LL-dd');
    rank = Number(match[2]);
  }
}

return [
  {
    json: {
      ...config,
      ok,
      is_review_callback: false,
      review_callback_valid: false,
      review_action: '',
      review_content_id: '',
      review_version: 0,
      user_error: userError,
      callback_query_id: String(callback.id || ''),
      callback_data: data,
      callback_user_id: callbackUserId,
      callback_chat_id: callbackChatId,
      discovery_date: discoveryDate,
      rank,
    },
  },
];

const row = $input.first()?.json || {};
const request = $('04. Parse — Callback Selection').first().json;
const title = String(row.title || '').trim();
const source = String(row.source || '').trim();
const url = String(row.url || '').trim();
const query = String(row.query || '').trim();
const rowDate = String(row.discovery_date || '').trim();
const rowRank = Number(row.rank || 0);
const topicFound =
  Boolean(title) &&
  rowDate === request.discovery_date &&
  rowRank === request.rank;

return [
  {
    json: {
      ...request,
      topic_found: topicFound,
      user_error: topicFound
        ? ''
        : 'The selected topic was not found. Please run the discovery workflow again.',
      topic_title: topicFound ? title : '',
      topic_source: topicFound ? source : '',
      topic_url: topicFound ? url : '',
      discovery_query: topicFound ? query : '',
    },
  },
];

const input = $input.first()?.json || {};
let candidate = input.output ?? input;

if (typeof candidate === 'string') {
  try {
    candidate = JSON.parse(candidate);
  } catch {
    candidate = {};
  }
}

const topic = $('08. Resolve — Selected Topic').first().json;
const normalizeCaption = (value) =>
  value
    .replace(/\\r\\n/g, '\n')
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '\n')
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map((line) => line.trimEnd())
    .join('\n')
    .trim();

const caption = typeof candidate.caption === 'string'
  ? normalizeCaption(candidate.caption)
  : '';
const hashtags = Array.isArray(candidate.hashtags)
  ? candidate.hashtags.map((tag) => String(tag).trim())
  : [];
const headerText = typeof candidate.headerText === 'string'
  ? candidate.headerText.trim()
  : '';
const rawHighlightWords = Array.isArray(candidate.highlightWords)
  ? candidate.highlightWords
  : [];
const highlightWords = rawHighlightWords.map((word) =>
  typeof word === 'string' ? word.trim() : '',
);

const stripSurroundingPunctuation = (word) =>
  word.replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu, '');

const headerWords = headerText
  .split(/\s+/u)
  .map(stripSurroundingPunctuation)
  .filter(Boolean);
const normalizedHighlightWords = highlightWords.map(stripSurroundingPunctuation);

const hasCaption = caption.length > 0;
const hasThreeHashtags = hashtags.length === 3;
const hasHeaderText = headerText.length > 0;
const hasHighlightWords = Array.isArray(candidate.highlightWords);
const hasTwoHighlightWords = highlightWords.length === 2;
const hasSingleWordItems = highlightWords.every(
  (word) => word.length > 0 && /^\S+$/u.test(word),
);
const hasWordCharacters = normalizedHighlightWords.every((word) => word.length > 0);
const hasDistinctHighlightWords =
  hasTwoHighlightWords &&
  hasWordCharacters &&
  new Set(normalizedHighlightWords).size === 2;
const highlightsBelongToHeader =
  hasTwoHighlightWords &&
  hasSingleWordItems &&
  hasWordCharacters &&
  normalizedHighlightWords.every((word) => headerWords.includes(word));

const isValid =
  hasCaption &&
  hasThreeHashtags &&
  hasHeaderText &&
  hasHighlightWords &&
  hasTwoHighlightWords &&
  hasSingleWordItems &&
  hasDistinctHighlightWords &&
  highlightsBelongToHeader;
const errors = [];

if (!hasCaption) {
  errors.push('caption is required');
}

if (!hasThreeHashtags) {
  errors.push('hashtags must contain exactly 3 items');
}

if (!hasHeaderText) {
  errors.push('headerText is required');
}

if (!hasHighlightWords) {
  errors.push('highlightWords is required');
}

if (hasHighlightWords && !hasTwoHighlightWords) {
  errors.push('highlightWords must contain exactly 2 items');
}

if (hasHighlightWords && !hasSingleWordItems) {
  errors.push('highlightWords items must each contain exactly one non-whitespace word');
}

if (
  hasHighlightWords &&
  hasTwoHighlightWords &&
  hasSingleWordItems &&
  !hasDistinctHighlightWords
) {
  errors.push('highlightWords must contain 2 distinct words');
}

if (
  hasHighlightWords &&
  hasTwoHighlightWords &&
  hasSingleWordItems &&
  hasDistinctHighlightWords &&
  !highlightsBelongToHeader
) {
  errors.push(
    'highlightWords must match individual words in headerText exactly, including spelling and capitalization',
  );
}

const assembled = caption + '\n\n' + hashtags.join(' ');

return [
  {
    json: {
      valid: isValid,
      isValid,
      validation_errors: errors,
      candidate: {
        caption,
        hashtags,
        headerText,
        highlightWords,
      },
      caption,
      hashtags,
      headerText,
      highlightWords,
      assembled_text: assembled,
      topic_title: topic.topic_title,
    },
  },
];

const approved = $input.first().json;
const config = $('02. Config — Project Settings').first().json;
const topic = $('08. Resolve — Selected Topic').first().json;
const selectedNews = $('07. Read — Selected Daily News').first().json;

if (!approved.valid) {
  throw new Error('Refusing to prepare an invalid content row');
}

const resultId = String(selectedNews.result_id || '').trim();

if (!resultId) {
  throw new Error('Selected Daily News row is missing result_id');
}

const requestedVersion =
  approved.version ??
  approved.request_version ??
  topic.version ??
  1;
const version = Number(requestedVersion);

if (!Number.isInteger(version) || ![1, 2].includes(version)) {
  throw new Error('Content version must be 1 or 2');
}

const hashResultId = (value) => {
  let hash = 14695981039346656037n;
  const prime = 1099511628211n;

  for (const character of value) {
    hash ^= BigInt(character.codePointAt(0));
    hash = BigInt.asUintN(64, hash * prime);
  }

  return hash.toString(16).padStart(16, '0');
};

const topicId = `topic_${hashResultId(resultId)}`;
const contentId = `content_${topicId}`;
const manilaNow = DateTime.now().setZone(config.timezone);
const driveFilename = `${contentId}_v${version}.png`;

return [
  {
    json: {
      create_at: manilaNow.toISO(),
      topic_title: topic.topic_title,
      caption: approved.caption,
      hashtags: approved.hashtags.join(' '),
      header_text: approved.headerText,
      highlight_words: approved.highlightWords.join(', '),
      topic_id: topicId,
      content_id: contentId,
      version,
      image_url: '',
      drive_filename: driveFilename,
    },
  },
];

