={{ (() => {
  const row = $('18. Prepare — Approved Daily Topic Row').first().json;
  const escapeHtml = (value) =>
    String(value || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');

  const normalizedCaption = String(row.caption || '')
    .replace(/\r\n?/g, '\n')
    .trim();
  const captionLines = normalizedCaption.split('\n');
  const sourceIndex = captionLines.findIndex((line) =>
    /^\s*Source:\s*/i.test(line),
  );

  let captionBody = normalizedCaption;
  let sourceValue = '';
  let captionTail = '';

  if (sourceIndex >= 0) {
    captionBody = captionLines.slice(0, sourceIndex).join('\n').trim();
    sourceValue = captionLines[sourceIndex]
      .replace(/^\s*Source:\s*/i, '')
      .trim();
    captionTail = captionLines.slice(sourceIndex + 1).join('\n').trim();
  }

  const message = [
    '📰 <b>Topic:</b>',
    escapeHtml(row.topic_title),
    '',
    '📝 <b>HeaderText:</b>',
    '<b>' + escapeHtml(row.header_text) + '</b>',
    '',
    '✨ <b>HighlightWords:</b>',
    '<b>' + escapeHtml(row.highlight_words) +'</b>',
    '',
    '✍️ <b>Caption:</b>',
    '',
    escapeHtml(captionBody),
  ];

  if (sourceValue) {
    message.push('', '🔗 <b>Source:</b> ' + escapeHtml(sourceValue));
  }

  if (captionTail) {
    message.push('', escapeHtml(captionTail));
  }

  message.push('', escapeHtml(row.hashtags));

  return message.join('\n');
})() }}
